import os, re, json

def load_grids():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load_grids()

# Try to apply "flood fill from outside" rule and see if it matches demo
def transform(grid):
    h, w = len(grid), len(grid[0])
    # Create visited array for 0s reachable from outside
    visited = [[False]*w for _ in range(h)]

    # Start flood fill from all 0s on the boundary
    for i in range(h):
        for j in range(w):
            if grid[i][j] == 0 and (i == 0 or i == h-1 or j == 0 or j == w-1):
                if not visited[i][j]:
                    queue = [(i,j)]
                    while queue:
                        xi, xj = queue.pop(0)
                        if visited[xi][xj]:
                            continue
                        visited[xi][xj] = True
                        for di, dj in [(0,1),(0,-1),(1,0),(-1,0)]:
                            ni, nj = xi+di, xj+dj
                            if 0 <= ni < h and 0 <= nj < w and not visited[ni][nj] and grid[ni][nj] == 0:
                                queue.append((ni,nj))

    # Mark unreached 0s as 2
    result = [row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            if grid[i][j] == 0 and not visited[i][j]:
                result[i][j] = 2
    return result

