# Try: Find the minimal bounding rectangle of ALL non-zero cells, fill interior
def transform_rect(grid):
    h, w = len(grid), len(grid[0])

    # Find all positions of non-zero cells
    nz_positions = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] != 0:
                nz_positions.append((i,j))

    if not nz_positions:
        return [row[:] for row in grid]

    # Compute bounding box
    min_r, max_r = min(p[0] for p in nz_positions), max(p[0] for p in nz_positions)
    min_c, max_c = min(p[1] for p in nz_positions), max(p[1] for p in nz_positions)

    # Fill interior (excluding boundary)
    result = [row[:] for row in grid]
    for i in range(min_r + 1, max_r):
        for j in range(min_c + 1, max_c):
            if grid[i][j] == 0:
                result[i][j] = 2

    return result

