def flood_fill_diagonal(grid, visited):
    """Mark all 0s reachable from boundary using 8-way movement."""
    h, w = len(grid), len(grid[0])

    # Start from all 0s on boundary
    queue = []
    for i in range(h):
        for j in range(w):
            if grid[i][j] == 0 and (i == 0 or i == h-1 or j == 0 or j == w-1):
                queue.append((i,j))
                visited[i][j] = True

    while queue:
        i, j = queue.pop(0)
        # Try all 8 neighbors
        for di in [-1, 0, 1]:
            for dj in [-1, 0, 1]:
                if di == 0 and dj == 0:
                    continue
                ni, nj = i + di, j + dj
                if 0 <= ni < h and 0 <= nj < w:
                    if not visited[ni][nj] and grid[ni][nj] == 0:
                        visited[ni][nj] = True
                        queue.append((ni, nj))

